import React, { useEffect, useState } from "react";
import axios from "axios";

const ZenMessage = () => {
  const [gitHubZenMessage, setGitHubZenMessage] = useState("Loading thoughts...");
  const [gitHubZenErrorMessage, setGitHubZenErrorMessage] = useState("");

  useEffect(() => {
    let isMounted = true;
    const fetchData = async () => {
      try {
        const { data: apiResponse } = await axios.get(
          "https://api.github.com/zen"
        );
        if (isMounted) {
          setGitHubZenMessage(apiResponse);
          setGitHubZenErrorMessage("");
        }
      } catch (error) {
        if (isMounted) {
          setGitHubZenMessage("Always push your limits.");
          setGitHubZenErrorMessage(
            error.response 
              ? `[status error ${error.response.status}]: ${error.response.data?.message || 'Failed to connect'}`
              : "Failed to connect to GitHub API."
          );
        }
      }
    };
    fetchData();
    return () => {
      isMounted = false;
    };
  }, []);

  return (
    <div className="w-full bg-white border-2 border-black rounded shadow-md select-none text-black transition-all hover:shadow-lg">
      {/* Message Content (Clean card box without title bar) */}
      <div className="p-5 sm:p-6 md:p-8 text-center bg-white">
        <p className="font-sans font-semibold text-lg sm:text-2xl md:text-3xl leading-snug italic text-black m-0">
          "{gitHubZenMessage}"
        </p>
        {gitHubZenErrorMessage && (
          <p className="text-[10px] text-destructive m-0 mt-3 font-mono">
            {gitHubZenErrorMessage}
          </p>
        )}
      </div>
    </div>
  );
};

export default ZenMessage;
